"use client"

import { useState, useEffect } from "react"
import { startSession, endSession } from "../api"

const SessionStarter = ({ currentSession, onSessionStart, onSessionEnd }) => {
  const [loading, setLoading] = useState(false)
  const [showCountdownInput, setShowCountdownInput] = useState(false)
  const [countdownMinutes, setCountdownMinutes] = useState(25)
  const [timeRemaining, setTimeRemaining] = useState(null)
  const [isCountdownActive, setIsCountdownActive] = useState(false)

  // Countdown timer effect
  useEffect(() => {
    let interval = null

    if (isCountdownActive && timeRemaining > 0) {
      interval = setInterval(() => {
        setTimeRemaining((time) => {
          if (time <= 1) {
            setIsCountdownActive(false)
            // Auto-end session when countdown reaches zero
            if (currentSession) {
              handleEndSession()
            }
            // Show completion notification
            showCountdownComplete()
            return 0
          }
          return time - 1
        })
      }, 1000)
    } else if (!isCountdownActive) {
      clearInterval(interval)
    }

    return () => clearInterval(interval)
  }, [isCountdownActive, timeRemaining, currentSession])

  const showCountdownComplete = () => {
    // Create a beautiful completion notification
    const notification = document.createElement("div")
    notification.className = "countdown-complete-notification"
    notification.innerHTML = `
      <div class="notification-content">
        <div class="notification-icon">🎉</div>
        <h3>Focus Session Complete!</h3>
        <p>Great job! You've completed your ${countdownMinutes}-minute focus session.</p>
      </div>
    `
    document.body.appendChild(notification)

    setTimeout(() => {
      notification.remove()
    }, 5000)
  }

  const handleStartSession = async () => {
    setLoading(true)
    try {
      const response = await startSession()
      onSessionStart(response.session)

      // Start countdown if enabled
      if (showCountdownInput && countdownMinutes > 0) {
        setTimeRemaining(countdownMinutes * 60)
        setIsCountdownActive(true)
      }

      setShowCountdownInput(false)
    } catch (error) {
      console.error("Failed to start session:", error)
      alert("Failed to start session. Please try again.")
    } finally {
      setLoading(false)
    }
  }

  const handleEndSession = async () => {
    if (!currentSession) return

    setLoading(true)
    try {
      await endSession(currentSession.id)
      onSessionEnd()
      setIsCountdownActive(false)
      setTimeRemaining(null)
    } catch (error) {
      console.error("Failed to end session:", error)
      alert("Failed to end session. Please try again.")
    } finally {
      setLoading(false)
    }
  }

  const formatTime = (seconds) => {
    const hours = Math.floor(seconds / 3600)
    const minutes = Math.floor((seconds % 3600) / 60)
    const secs = seconds % 60

    if (hours > 0) {
      return `${hours}:${minutes.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`
    }
    return `${minutes}:${secs.toString().padStart(2, "0")}`
  }

  const getCountdownColor = () => {
    if (!timeRemaining) return "var(--neon-blue)"
    const percentage = (timeRemaining / (countdownMinutes * 60)) * 100
    if (percentage > 50) return "var(--neon-green)"
    if (percentage > 25) return "var(--neon-orange)"
    return "var(--neon-pink)"
  }

  const getCountdownPercentage = () => {
    if (!timeRemaining || !countdownMinutes) return 100
    return (timeRemaining / (countdownMinutes * 60)) * 100
  }

  return (
    <div className="session-starter">
      {/* Countdown Timer Display */}
      {currentSession && isCountdownActive && timeRemaining !== null && (
        <div className="countdown-display">
          <div className="countdown-circle">
            <svg className="countdown-svg" viewBox="0 0 100 100">
              <circle
                className="countdown-track"
                cx="50"
                cy="50"
                r="45"
                fill="none"
                stroke="rgba(255, 255, 255, 0.1)"
                strokeWidth="8"
              />
              <circle
                className="countdown-progress"
                cx="50"
                cy="50"
                r="45"
                fill="none"
                stroke={getCountdownColor()}
                strokeWidth="8"
                strokeLinecap="round"
                style={{
                  strokeDasharray: `${2 * Math.PI * 45}`,
                  strokeDashoffset: `${2 * Math.PI * 45 * (1 - getCountdownPercentage() / 100)}`,
                  transform: "rotate(-90deg)",
                  transformOrigin: "50% 50%",
                  transition: "stroke-dashoffset 1s ease-in-out, stroke 0.3s ease",
                }}
              />
            </svg>
            <div className="countdown-time">
              <span className="countdown-number">{formatTime(timeRemaining)}</span>
              <span className="countdown-label">remaining</span>
            </div>
          </div>
          <div className="countdown-info">
            <h4>Focus Session in Progress</h4>
            <p>Stay focused! You're doing great.</p>
          </div>
        </div>
      )}

      <div className="session-status">
        {currentSession ? (
          <div className="active-session">
            <div className="status-indicator active"></div>
            <div className="session-info">
              <h3>Focus Session Active</h3>
              <p>Started at {new Date(currentSession.startedAt).toLocaleTimeString()}</p>
              {isCountdownActive && <p className="countdown-status">🎯 {countdownMinutes}-minute focus session</p>}
            </div>
          </div>
        ) : (
          <div className="inactive-session">
            <div className="status-indicator inactive"></div>
            <div className="session-info">
              <h3>Ready to Focus</h3>
              <p>Start a new session to begin monitoring</p>
            </div>
          </div>
        )}
      </div>

      {/* Countdown Input Section */}
      {!currentSession && (
        <div className="countdown-setup">
          <div className="countdown-toggle">
            <label className="toggle-switch">
              <input
                type="checkbox"
                checked={showCountdownInput}
                onChange={(e) => setShowCountdownInput(e.target.checked)}
              />
              <span className="toggle-slider"></span>
              <span className="toggle-label">Set Focus Timer</span>
            </label>
          </div>

          {showCountdownInput && (
            <div className="countdown-input-section">
              <div className="countdown-input-container">
                <label htmlFor="countdown-minutes">Focus Duration (minutes)</label>
                <div className="input-with-controls">
                  <button
                    type="button"
                    className="input-control decrease"
                    onClick={() => setCountdownMinutes(Math.max(1, countdownMinutes - 5))}
                  >
                    −
                  </button>
                  <input
                    id="countdown-minutes"
                    type="number"
                    min="1"
                    max="180"
                    value={countdownMinutes}
                    onChange={(e) => setCountdownMinutes(Math.max(1, Number.parseInt(e.target.value) || 1))}
                    className="countdown-input"
                  />
                  <button
                    type="button"
                    className="input-control increase"
                    onClick={() => setCountdownMinutes(Math.min(180, countdownMinutes + 5))}
                  >
                    +
                  </button>
                </div>
                <div className="preset-buttons">
                  <button
                    type="button"
                    className={`preset-btn ${countdownMinutes === 15 ? "active" : ""}`}
                    onClick={() => setCountdownMinutes(15)}
                  >
                    15m
                  </button>
                  <button
                    type="button"
                    className={`preset-btn ${countdownMinutes === 25 ? "active" : ""}`}
                    onClick={() => setCountdownMinutes(25)}
                  >
                    25m
                  </button>
                  <button
                    type="button"
                    className={`preset-btn ${countdownMinutes === 45 ? "active" : ""}`}
                    onClick={() => setCountdownMinutes(45)}
                  >
                    45m
                  </button>
                  <button
                    type="button"
                    className={`preset-btn ${countdownMinutes === 60 ? "active" : ""}`}
                    onClick={() => setCountdownMinutes(60)}
                  >
                    60m
                  </button>
                </div>
                <p className="countdown-preview">
                  ⏱️ Your focus session will last <strong>{countdownMinutes} minutes</strong>
                </p>
              </div>
            </div>
          )}
        </div>
      )}

      <div className="session-controls">
        {currentSession ? (
          <button onClick={handleEndSession} disabled={loading} className="btn btn-danger">
            {loading ? "Ending..." : "End Session"}
          </button>
        ) : (
          <button onClick={handleStartSession} disabled={loading} className="btn btn-primary">
            {loading
              ? "Starting..."
              : showCountdownInput
                ? `Start ${countdownMinutes}min Focus`
                : "Start Focus Session"}
          </button>
        )}
      </div>

      <div className="session-tips">
        <h4>Tips for Better Focus:</h4>
        <ul>
          <li>Find a quiet, well-lit environment</li>
          <li>Position your camera at eye level</li>
          <li>Minimize distractions around you</li>
          <li>Take breaks every 25-30 minutes</li>
          <li>Use the Pomodoro Technique (25min focus + 5min break)</li>
        </ul>
      </div>
    </div>
  )
}

export default SessionStarter
